#include <stdint.h>
#include <stdbool.h>

// Motor status
typedef enum {
    MOTOR_STATUS_IDLE = 0,
    MOTOR_STATUS_ENABLED,
    MOTOR_STATUS_RUNNING,
    MOTOR_STATUS_FAULT,
    MOTOR_STATUS_DISABLED
} MotorStatus;

// Protocol types
typedef enum {
    PROTOCOL_CAN = 0,
    PROTOCOL_RS485,
    PROTOCOL_ETHERCAT,
    PROTOCOL_COUNT
} ProtocolType;

// Frame types
typedef enum {
    FRAME_TYPE_STATUS_REPORT = 0x01,
    FRAME_TYPE_POSITION_CMD = 0x02,
    FRAME_TYPE_VELOCITY_CMD = 0x03,
    FRAME_TYPE_TORQUE_CMD = 0x04,
    FRAME_TYPE_PARAM_READ = 0x05,
    FRAME_TYPE_PARAM_WRITE = 0x06,
    FRAME_TYPE_FIRMWARE_UPDATE = 0x08
} FrameType;

// Unified frame structure (64 bytes)
typedef struct {
    uint8_t header[2];        // 0xAA 0x55
    uint8_t frame_type;
    uint8_t node_id;
    uint8_t reserved[2];
    uint32_t timestamp;
    uint8_t payload[56];
    uint16_t crc16;
} Frame;

// Motor configuration
typedef struct {
    uint8_t motor_id;
    float rated_voltage;
    float rated_current;
    float rated_torque;
    float max_velocity;
    float max_torque;
    float gearbox_ratio;
    uint16_t encoder_resolution;
    float kp, ki, kd;
    float max_velocity_limit;
    float max_torque_limit;
} MotorConfig;

// PID controller
typedef struct {
    float kp, ki, kd;
    float output_min, output_max;
    float integral;
    float prev_error;
} PIDController;

// Logger levels
typedef enum {
    LOG_ERROR = 0,
    LOG_WARN,
    LOG_INFO,
    LOG_DEBUG
} LogLevel;
